mapper.select:
select  obase.*,gg.shop_gate_name,gg.detail_address,gg.longitude,gg.latitude,ui.user_mobile,ui.user_name,gg.province,gg.city,gg.county
from  ${database.prefix.order}hou_order_base obase
LEFT JOIN ${database.prefix.business}hou_shop_gate gg ON gg.shop_gate_id=obase.order_gate_shop_id
LEFT JOIN ${database.prefix.userms}hou_user_info ui ON ui.user_id=obase.buyer_user_id

    obase.is_delivery = '1' and
    obase.shop_affirm = '1'

        and obase.order_id = #{param.orderId}


        and obase.buyer_user_name = #{param.buyerUserName}


        and obase.order_status = #{param.status}


        and obase.is_delivery_del = #{param.isDeliveryDel}


        and obase.distributor_id = #{param.distributorId}


        and obase.pickup = #{param.pickup}


order by obase.order_create_time desc

select obase.*,gg.shop_gate_name,gg.detail_address,gg.longitude,gg.latitude,ui.user_mobile,ui.user_name,yb.rider_name,yb.rider_tel from ${database.prefix.order}hou_order_base obase LEFT JOIN ${database.prefix.business}hou_shop_gate gg ON gg.shop_gate_id=obase.order_gate_shop_id LEFT JOIN ${database.prefix.userms}hou_user_info ui ON ui.user_id=obase.buyer_user_id LEFT JOIN `mall-rider`.rider_base yb ON yb.rider_id=obase.distributor_id
obase.is_delivery = '1'
and obase.order_id like concat('%',#{param.orderId},'%')
and obase.buyer_user_name like concat('%',#{param.buyerUserName},'%')
and obase.order_status = #{param.status}
and obase.is_delivery_del = #{param.isDeliveryDel}
and obase.distributor_id = 0
and obase.distributor_id > 0
and obase.pickup = #{param.pickup}
order by obase.order_create_time desc

select  count(1) from  ${database.prefix.order}hou_order_base ob where ob.is_delivery = '1' and ob.shop_affirm = '1'

    and pickup = #{pickup}


    and order_status = #{orderStatus}


    and distributor_id = #{userId}
